// ─── File: TokenPropagationDemo.java ───
// Runnable demo: forward token, inject claims, token exchange — all over mTLS.
package com.bank.tokenprop;

import java.util.*;
import java.util.logging.*;

public class TokenPropagationDemo {

    private static final Logger log = Logger.getLogger("TokenProp");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Gateway gateway = new Gateway();
        MtlsChannel channel = new MtlsChannel("gateway-cert");   // gateway is a verified peer
        TransferService transfer = new TransferService();

        String userToken = "rajesh|CUSTOMER|TRANSFER|valid-sig";   // already validated at edge

        // 1) FORWARD: pass the same bearer token; downstream re-validates.
        Map<String, String> fwd = gateway.propagate("FORWARD", userToken);
        transfer.handle(channel, fwd);

        // 2) INJECT_CLAIMS: gateway verifies once, forwards trusted headers.
        Map<String, String> inj = gateway.propagate("INJECT_CLAIMS", userToken);
        transfer.handle(channel, inj);

        // 3) TOKEN_EXCHANGE: swap for a narrow token scoped to transfer-service only.
        Map<String, String> exch = gateway.propagate("TOKEN_EXCHANGE", userToken);
        transfer.handle(channel, exch);

        // 4) ATTACK: external caller tries to inject X-User headers over an UNVERIFIED channel.
        MtlsChannel rogue = new MtlsChannel("unknown-cert");
        Map<String, String> forged = Map.of("X-User-Id", "rajesh", "X-User-Roles", "ADMIN");
        try { transfer.handle(rogue, forged); }
        catch (SecurityException e) { log.severe("Rogue injected-claims REJECTED: " + e.getMessage()); }
    }
}

// ─── edge/Gateway.java (validates token, then applies a propagation strategy) ───
class Gateway {
    private static final Logger log = Logger.getLogger("TokenProp");
    Map<String, String> propagate(String strategy, String userToken) {
        // Gateway has ALREADY validated userToken (signature, exp, iss, aud).
        switch (strategy) {
            case "FORWARD":
                log.info("FORWARD: pass original Authorization header downstream");
                return Map.of("Authorization", "Bearer " + userToken, "mode", "FORWARD");
            case "INJECT_CLAIMS":
                log.info("INJECT_CLAIMS: strip token, forward verified X-User-* headers");
                return Map.of("X-User-Id", "rajesh", "X-User-Roles", "CUSTOMER,TRANSFER",
                        "mode", "INJECT_CLAIMS");
            case "TOKEN_EXCHANGE":
                String narrow = "rajesh|TRANSFER|aud=transfer-service|valid-sig";  // least privilege
                log.info("TOKEN_EXCHANGE: mint narrow token (aud=transfer-service)");
                return Map.of("Authorization", "Bearer " + narrow, "mode", "TOKEN_EXCHANGE");
            default: throw new IllegalArgumentException("unknown strategy");
        }
    }
}

// ─── transport/MtlsChannel.java (only a verified peer certificate is accepted) ───
class MtlsChannel {
    final String peerCert;
    MtlsChannel(String peerCert) { this.peerCert = peerCert; }
    boolean isTrustedPeer() { return "gateway-cert".equals(peerCert); }   // mesh-verified identity
}

// ─── service/TransferService.java (validates propagated identity + mTLS peer) ───
class TransferService {
    private static final Logger log = Logger.getLogger("TokenProp");
    void handle(MtlsChannel channel, Map<String, String> headers) {
        // Zero trust: first establish the CALLER is a trusted peer (mTLS).
        if (!channel.isTrustedPeer())
            throw new SecurityException("untrusted mTLS peer — cannot trust any headers");
        String mode = headers.get("mode");
        if ("FORWARD".equals(mode) || "TOKEN_EXCHANGE".equals(mode)) {
            String token = headers.get("Authorization").substring(7);
            // re-validate token (signature/exp/aud) — audience must match this service
            log.info(() -> "transfer authorized via " + mode + " token for "
                    + token.split("\\|")[0]);
        } else if ("INJECT_CLAIMS".equals(mode)) {
            // trusted only because peer is the gateway over mTLS
            log.info(() -> "transfer authorized via injected claims: user="
                    + headers.get("X-User-Id") + ", roles=" + headers.get("X-User-Roles"));
        } else {
            throw new SecurityException("no valid propagated identity");
        }
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
